require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);$memberId=current_member_id();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';try{
 if($a==='add_equipment'){$n=trim($_POST['name']??'');if(!$n)throw new RuntimeException('Completează denumirea.');$pdo->prepare('INSERT INTO house_water_equipment(name,kind,location,installed_date,model,serial_no,service_interval_days,notes,created_by_member_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$n,trim($_POST['kind']??'Dedurizator'),trim($_POST['location']??'')?:null,parse_ro_date($_POST['installed_date']??''),trim($_POST['model']??'')?:null,trim($_POST['serial_no']??'')?:null,(int)($_POST['service_interval_days']??0)?:null,trim($_POST['notes']??'')?:null,$memberId]);$message='Echipamentul a fost adăugat.';}
 if($a==='add_log'){$eid=(int)($_POST['equipment_id']??0);$date=parse_ro_date($_POST['action_date']??'')?:date('Y-m-d');$pdo->prepare('INSERT INTO house_water_logs(equipment_id,action_date,action_type,quantity,notes,next_due_date,created_by_member_id) VALUES(?,?,?,?,?,?,?)')->execute([$eid,$date,trim($_POST['action_type']??'Mentenanță'),trim($_POST['quantity']??'')?:null,trim($_POST['notes']??'')?:null,parse_ro_date($_POST['next_due_date']??''),$memberId]);$message='Operațiunea a fost salvată.';}
 if($a==='delete_equipment'){$pdo->prepare('DELETE FROM house_water_equipment WHERE id=?')->execute([(int)$_POST['id']]);$message='Echipamentul a fost șters.';}
}catch(Throwable $e){$error=$e->getMessage();}}
$equipment=$pdo->query('SELECT * FROM house_water_equipment ORDER BY id')->fetchAll();$logs=$pdo->query('SELECT l.*,e.name equipment_name,m.name creator FROM house_water_logs l JOIN house_water_equipment e ON e.id=l.equipment_id LEFT JOIN family_members m ON m.id=l.created_by_member_id ORDER BY l.action_date DESC,l.id DESC LIMIT 60')->fetchAll();
$pageTitle='Tratare apă';$active='more';$backUrl='/home.php';require __DIR__.'/includes/layout_top.php';?>
<?php if($message):?><div class="alert success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<section class="hero-card subtle"><div><h2>Tratare apă</h2><p>Dedurizator, sare, filtre și istoricul intervențiilor.</p></div><button class="btn primary small" data-open-sheet="waterEquipmentSheet"><?=icon('plus')?> Echipament</button></section>
<div class="house-card-grid"><?php foreach($equipment as $e):?><article class="house-info-card"><span class="house-section-icon"><?=icon('settings')?></span><div><b><?=e($e['name'])?></b><small><?=e($e['kind'])?><?=$e['location']?' · '.e($e['location']):''?></small><?php if($e['installed_date']):?><small>Montat: <?=e(date_ro($e['installed_date']))?></small><?php endif;?></div><button class="btn soft small" data-open-sheet="waterLogSheet" data-equipment="<?=$e['id']?>">Jurnal +</button></article><?php endforeach;?><?php if(!$equipment):?><div class="empty">Adaugă dedurizatorul sau filtrul din garaj.</div><?php endif;?></div>
<section class="section-head water-history-head"><div><h2>Istoric</h2><p>Sare, filtre, service și următoarele schimburi.</p></div></section><div class="reminder-list water-history-list"><?php foreach($logs as $l):?><article class="reminder-card"><span class="mini-icon green"><?=icon('check')?></span><div class="reminder-main"><strong><?=e($l['action_type'])?> · <?=e($l['equipment_name'])?></strong><span><?=e(date_ro($l['action_date']))?><?=$l['quantity']?' · '.e($l['quantity']):''?><?=$l['creator']?' · '.e($l['creator']):''?></span><?php if($l['next_due_date']):?><small>Următorul: <?=e(date_ro($l['next_due_date']))?></small><?php endif;?><?php if($l['notes']):?><small><?=e($l['notes'])?></small><?php endif;?></div></article><?php endforeach;?></div>
<div class="modal" id="waterEquipmentSheet" aria-hidden="true"><div class="modal-backdrop" data-close-sheet></div><section class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h2>Echipament nou</h2><button class="icon-btn" data-close-sheet><?=icon('close')?></button></div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_equipment"><label>Denumire<input name="name" required placeholder="Dedurizator"></label><label>Tip<select name="kind"><option>Dedurizator</option><option>Filtru</option><option>Osmoză</option><option>Altele</option></select></label><label>Locație<input name="location" placeholder="Garaj"></label><label>Data montării<input class="ro-date" name="installed_date" placeholder="ZZ.LL.AAAA"></label><div class="form-grid"><label>Model<input name="model"></label><label>Serie<input name="serial_no"></label></div><label>Interval service (zile)<input type="number" name="service_interval_days" min="0"></label><label>Notițe<textarea name="notes"></textarea></label><button class="btn primary wide">Salvează</button></form></section></div>
<div class="modal" id="waterLogSheet" aria-hidden="true"><div class="modal-backdrop" data-close-sheet></div><section class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h2>Adaugă în jurnal</h2><button class="icon-btn" data-close-sheet><?=icon('close')?></button></div><form method="post" class="form-stack" id="waterLogForm"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_log"><input type="hidden" name="equipment_id"><label>Operațiune<select name="action_type"><option>Adăugat sare</option><option>Schimb filtru</option><option>Service</option><option>Curățare</option><option>Verificare</option><option>Altele</option></select></label><label>Data<input class="ro-date" name="action_date" value="<?=date('d.m.Y')?>"></label><label>Cantitate / detaliu<input name="quantity" placeholder="Ex: 25 kg"></label><label>Următorul schimb / verificare<input class="ro-date" name="next_due_date" placeholder="ZZ.LL.AAAA"></label><label>Notițe<textarea name="notes"></textarea></label><button class="btn primary wide">Salvează</button></form></section></div>
